send-request.set-body:
@{
        var code        = (string)context.Variables["AuthCode"];
        var miToken     = (string)context.Variables["MiAssertionToken"];
        var clientId    = "{{apim-app-client-id}}";
        var gatewayUrl  = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
        var redirectUri = Uri.EscapeDataString(gatewayUrl + "/callback");
        return
          "grant_type=authorization_code"
          + "&client_id="            + Uri.EscapeDataString(clientId)
          + "&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
          + "&client_assertion="     + Uri.EscapeDataString(miToken)
          + "&code="                 + Uri.EscapeDataString(code)
          + "&redirect_uri="         + redirectUri;
      }

return-response.set-body:
@{
            var body = ((IResponse)context.Variables["TokenResponse"]).Body.As(preserveContent: true);
            return Newtonsoft.Json.JsonConvert.SerializeObject(new {
              error       = "token_exchange_failed",
              description = "The authorization code exchange failed.",
              details     = body
            });
          }
